			a, b := &fixture.Account{Epoch: 7}, &fixture.Account{Epoch: 8}
			r := &fixture.Registry{Entries: map[string]*fixture.Account{"k": a, "j": b}}
			copyRegistry := *r
			key := "k"
			done := r.D(key)
			counters(t, a, 1, 0)
			wantA, wantB := 0, 0
			switch scenario {
			case "unchanged":
				wantA = 1
			case "entry replacement":
				r.Entries["k"] = b
				wantB = 1
			case "delete":
				delete(r.Entries, "k")
			case "nil entry":
				r.Entries["k"] = nil
			case "nil map":
				r.Entries = nil
			case "reinsert":
