				r.Entries = map[string]*fixture.Account{"k": b}
				wantA = 1
			case "copy shares map":
				copyRegistry.Entries["k"] = b
				wantB = 1
			case "caller reassigns key":
				key = "j"
				if r.Entries[key] != b {
					t.Fatal("replacement key did not select b in caller")
				}
				wantA = 1
			}
			done()
			counters(t, a, 1, wantA)
			counters(t, b, 0, wantB)
		})
	}
}

